html:
{%- set cur = yht_currency(doc) -%}
<style>
.print-format { font-family: Arial, "Noto Sans", sans-serif; font-size: 9pt; color: #000; }
table.katc-doc { width: 100%; border-collapse: collapse; }
table.katc-doc > thead > tr > td { padding: 0; border: 0; }
/* The outer cell MUST be allowed to break. A table cell defaults to
   page-break-inside: avoid, which pushes the whole document onto one page and
   defeats the <thead> that repeats the letterhead. */
table.katc-doc > tbody > tr > td { padding: 0; border: 0; page-break-inside: auto !important; }
.katc-title { text-align: center; font-size: 14pt; font-weight: bold; letter-spacing: 1px; margin: 8px 0 0; }
.katc-title-ar { text-align: center; font-size: 12pt; font-weight: bold; direction: rtl; margin-bottom: 8px; }
.katc-meta { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.katc-meta td { border: 1px solid #999; padding: 3px 5px; font-size: 8.5pt; vertical-align: top; }
.katc-meta td.lbl { background: #f2f2f2; font-weight: bold; width: 18%; }
table.katc-items { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
/* Repeats the column headers on every page. */
table.katc-items thead { display: table-header-group; }
table.katc-items th, table.katc-items td { border: 1px solid #999; padding: 3px 5px; font-size: 8.5pt; vertical-align: top; }
table.katc-items th { background: #f2f2f2; text-align: center; font-size: 8pt; }
table.katc-items td.num { text-align: right; }
table.katc-items td.ctr { text-align: center; }
.katc-ar { direction: rtl; text-align: right; }
.katc-totals { width: 55%; margin-left: auto; border-collapse: collapse; page-break-inside: avoid; }
.katc-totals td { border: 1px solid #999; padding: 3px 6px; font-size: 8.5pt; }
.katc-totals td.lbl { background: #f2f2f2; font-weight: bold; }
.katc-totals td.num { text-align: right; }
.katc-grand td { font-weight: bold; font-size: 9.5pt; }
.katc-words { font-size: 8.5pt; margin: 6px 0; text-align: center; }
.katc-terms { font-size: 8pt; color: #333; margin-top: 6px; }
.katc-sign { width: 100%; margin-top: 20px; border-collapse: collapse; page-break-inside: avoid; }
.katc-sign td { width: 50%; font-size: 8.5pt; vertical-align: top; padding: 4px 8px; }
.katc-rule { border-bottom: 1px solid #000; height: 13px; }
.katc-bank { font-size: 8.5pt; line-height: 1.45; page-break-inside: avoid; }
.katc-qr img { width: 26mm; height: 26mm; }
#footer-html { font-size: 8pt; text-align: center; color: #444; }
/* wkhtmltopdf is handed this as --footer-html, which is the ONLY way the page
   spans resolve. In the browser print view it would render inline instead. */
.print-format-gutter #footer-html { display: none; }
</style>
<table class="katc-doc">
  <thead><tr><td>{% if letter_head and 'katc-lh' in letter_head %}{{ letter_head }}{% elif no_letterhead %}<div class="katc-spacer" style="height: {{ yht_katc_spacer_pt() }}pt"></div>{% endif %}</td></tr></thead>
  <tbody><tr><td>
{%- set ns = namespace(vat_rate=0) -%}
{%- for tax in doc.get("taxes") or [] -%}{%- if tax.charge_type == "On Net Total" -%}{%- set ns.vat_rate = ns.vat_rate + (tax.rate or 0) -%}{%- endif -%}{%- endfor -%}
{#- ERPNext has already split the tax per line. `ns.vat_rate` is only a FALLBACK,
    for a row `yht_row_taxes` has no entry for — see the helper docstring. -#}
{%- set rowtax = yht_row_taxes(doc) -%}
{#- An `Actual` freight or handling charge carries no `item_wise_tax_detail`, so
    `yht_row_taxes` leaves it out of the per-line split on purpose: it belongs to
    no line. Print it on a row of its own rather than spread it across a column
    headed TAX AMT on a Saudi tax invoice. -#}
{%- set itemwise_tax = rowtax.values()|sum -%}
{%- set other_charges = ((doc.total_taxes_and_charges or 0) - itemwise_tax) if rowtax else 0 -%}
<table style="width:100%"><tbody><tr>
  <td style="width:70%; vertical-align:top">
    <div style="font-size:8.5pt">Invoice Number / رقم الفاتورة &nbsp; <b>{{ doc.name }}</b></div>
  </td>
  <td style="width:30%; text-align:right; vertical-align:top">
    <div class="katc-title-ar" style="margin:0">فاتورة ضريبية</div>
    <div style="font-size:12pt; font-weight:bold; text-align:right">TAX INVOICE</div>
{%- set qr = yht_zatca_qr(doc) %}
{%- if qr %}
    <div class="katc-qr"><img src="data:image/png;base64,{{ qr }}" alt="ZATCA QR"></div>
{%- endif %}
  </td>
</tr></tbody></table>

<table class="katc-meta"><tbody>
  <tr>
    <td class="lbl">Time / الوقت</td><td>{# posting_time is stored with microseconds (09:44:19.116449 on KSIN-26-0608) and a customer-facing invoice must not print them #}{{ ((doc.posting_time or "")|string).split(".")[0] }}</td>
    <td class="lbl">Invoice Type</td><td>{{ doc.get("custom_payment_mode") or "" }}</td>
  </tr>
  <tr>
    <td class="lbl">Sales Executive</td><td>{{ yht_sales_person(doc) }}</td>
    <td class="lbl">Invoice Issue Date / تاريخ اصدار الفاتورة</td><td>{{ yht_date(doc.posting_date) }}</td>
  </tr>
  <tr>
    <td class="lbl">PO#</td><td>{{ doc.po_no or "" }}</td>
    <td class="lbl">Delivery Note</td><td>{{ doc.items[0].delivery_note if doc.items and doc.items[0].get("delivery_note") else "" }}</td>
  </tr>
</tbody></table>

{%- set addr = yht_national_address(doc, "customer_address") %}
<div style="font-weight:bold; font-size:9.5pt; margin-bottom:4px">Buyer - العميل</div>
<table class="katc-meta"><tbody>
  <tr>
    <td class="lbl">Name / الإسم</td><td colspan="3">{{ doc.customer_name or doc.customer or "" }}</td>
  </tr>
  <tr>
    <td class="lbl">VAT Number - الرقم الضريبي</td><td>{{ yht_party_vat(doc) }}</td>
    <td class="lbl">Country - البلد</td><td>{{ addr.country }}</td>
  </tr>
  <tr>
    <td class="lbl">Building No. - رقم المبني</td><td>{{ addr.building }}</td>
    <td class="lbl">Street Name - اسم الشارع</td><td>{{ addr.street }}</td>
  </tr>
  <tr>
    <td class="lbl">District - الحي</td><td>{{ addr.district }}</td>
    <td class="lbl">City - المدينة</td><td>{{ addr.city }}</td>
  </tr>
  <tr>
    <td class="lbl">Post Code - الرمز البريدي</td><td>{{ addr.pincode }}</td>
    <td class="lbl">Additional No. - الرقم الإضافي</td><td>{{ addr.additional }}</td>
  </tr>
  <tr>
    {#- Deliberately blank (Q3). The label row prints so the layout matches the
        artefact; there is no honest ERPNext source for a buyer CR on this site. -#}
    <td class="lbl">CR Number - رقم السجل التجاري</td><td colspan="3"></td>
  </tr>
</tbody></table>

<table class="katc-items">
  <thead><tr>
    <th style="width:5%">SN<div class="katc-ar">رقم</div></th>
    <th>ITEMS<div class="katc-ar">وصف</div></th>
    <th style="width:9%">QTY<div class="katc-ar">كمية</div></th>
    <th style="width:12%">Unit Rate<div class="katc-ar">سعر الوحدة</div></th>
    <th style="width:13%">EX VAT AMT<div class="katc-ar">مبلغ ضريبة القيمة المضافة</div></th>
    <th style="width:12%">TAX AMT<div class="katc-ar">مبلغ الضريبة</div></th>
    <th style="width:14%">Total Inc.Vat<div class="katc-ar">الإجمالي شاملاً ضريبة القيمة المضافة</div></th>
  </tr></thead>
  <tbody>
{%- for row in doc.items %}
{%- set row_net = row.net_amount or row.amount or 0 %}
{%- set row_tax = rowtax.get(row.name, row_net * ns.vat_rate / 100) %}
    <tr>
      <td class="ctr">{{ loop.index }}</td>
      <td>{{ row.item_name or row.item_code or "" }}
{%- set ar = yht_item_ar_rtl(row) %}{% if ar %}<div class="katc-ar">{{ ar }}</div>{% endif %}</td>
      <td class="ctr">{{ row.qty }} {{ row.uom or row.stock_uom or "" }}</td>
      <td class="num">{{ yht_money(row.rate, cur) }}</td>
      <td class="num">{{ yht_money(row_net, cur) }}</td>
      <td class="num">{{ yht_money(row_tax, cur) }}</td>
      <td class="num">{{ yht_money(row_net + row_tax, cur) }}</td>
    </tr>
{%- endfor %}
  </tbody>
</table>

<table class="katc-totals"><tbody>
  <tr><td class="lbl">Total (Excluding VAT) - الإجمالي غير شامل الضريبة</td><td class="num">{{ yht_money(doc.total, cur) }}</td></tr>
  <tr><td class="lbl">Total Taxable Amount (Excluding VAT) - الإجمالي الخاضع للضريبة</td><td class="num">{{ yht_money(doc.net_total, cur) }}</td></tr>
  <tr><td class="lbl">VAT Amount{% if ns.vat_rate %} {{ "%g"|format(ns.vat_rate) }}%{% endif %} - مبلغ الضريبة</td><td class="num">{{ yht_money(itemwise_tax if rowtax else doc.total_taxes_and_charges, cur) }}</td></tr>
{%- if other_charges|abs > 0.005 %}
  <tr><td class="lbl">Other Charges - رسوم أخرى</td><td class="num">{{ yht_money(other_charges, cur) }}</td></tr>
{%- endif %}
  <tr class="katc-grand"><td class="lbl">Net Total - الإجمالي</td><td class="num">{{ yht_money(doc.rounded_total or doc.grand_total, cur) }}</td></tr>
</tbody></table>

<div class="katc-words">{{ doc.in_words or "" }}</div>
{#- The Arabic in-words row stays present and EMPTY by decision (Q4). -#}
<div class="katc-words katc-ar"></div>

<div class="katc-terms"><b>Terms and Conditions - الشروط والأحكام</b><br>{{ doc.terms or "" }}</div>
<div style="margin-top:20px; font-size:8.5pt"><b>Received By :</b><div class="katc-rule" style="width:45%"></div></div>
  </td></tr></tbody>
</table>
<div id="footer-html">Page <span class="page"></span> of <span class="topage"></span></div>
